namespace Tests\Feature;

use Illuminate\Foundation\Testing\TestCase as BaseTestCase;

class TableTest extends BaseTestCase
{
    private string $tableHtml = <<<HTML
        <table>
            <thead>
                <tr>
                    <th></th>
                    <th><strong>Carbon black</strong></th>
                    <th><strong>Lead white</strong></th>
                </tr>
            </thead>
            <tbody>
                <tr>
                    <td><strong><em>Untitled</em>, 1934</strong></td>
                    <td></td>
                    <td>X<sup>2</sup></td>
                </tr>
            </tbody>
        </table>
        HTML;

    public function test_it_renders_header_cells(): void
    {
        $view = $this->view('components.molecules._m-table', ['tableHtml' => $this->tableHtml]);

        $this->assertEquals(3, preg_match_all('/<th[\s>]/', $view), 'Every header cell is rendered');
        $view->assertSeeInOrder(['Carbon black', 'Lead white']);
    }

    public function test_it_renders_body_cells(): void
    {
        $view = $this->view('components.molecules._m-table', ['tableHtml' => $this->tableHtml]);

        $this->assertEquals(3, substr_count($view, '<td'), 'Every body cell is rendered');
        $view->assertSee('X<sup>2</sup>', false);
    }

    public function test_it_renders_the_first_body_cell_as_a_side_header(): void
    {
        $view = $this->view('components.molecules._m-table', [
            'tableHtml' => $this->tableHtml,
            'hasSideHeader' => true,
        ]);

        $this->assertEquals(4, preg_match_all('/<th[\s>]/', $view), 'The first cell of each body row is a header');
        $this->assertEquals(2, substr_count($view, '<td'));
    }
}
